use ingetrazo_core::composition::{Sheet,SheetItem};use serde_json::json;
fn main(){let a:Vec<_>=std::env::args().collect();let mut scene=ingetrazo_formats::load_igz(std::path::Path::new(&a[1])).unwrap();scene.camera.yaw=-0.9;scene.camera.pitch=0.35;scene.camera.distance=9.;scene.camera.fov_deg=52.;scene.camera.target=glam::DVec3::new(2.,3.,4.);scene.camera.perspective=true;scene.camera.two_point=false;let frames:Vec<_>=scene.sheets[0].items.iter().filter_map(|i|if let SheetItem::ViewFrame(f)=i{Some(f.clone())}else{None}).collect();let mut out=vec![];for f in &frames{let before=scene.clone();let c=ingetrazo_gui::composer::camera_for_frame(&scene,f);assert_eq!(scene,before);out.push(json!({"camera":c,"eye":c.eye().to_array(),"view_matrix":c.view_matrix().to_cols_array(),"projection_matrix":c.projection_matrix().to_cols_array()}));}let mut fresh=scene.clone();fresh.sheets=vec![Sheet::default()];fresh.sheets[0].items=frames.into_iter().map(SheetItem::ViewFrame).collect();ingetrazo_formats::save_igz(&fresh,std::path::Path::new(&a[3])).unwrap();std::fs::write(&a[2],serde_json::to_vec_pretty(&out).unwrap()).unwrap();}
